
# All code generated by AI
# Purpose of this file is strictly to generate a csv file containing relevant currency data

import yfinance as yf
import pandas as pd

ticker = "USDEGP=X"

# 1. Download daily forex data
try:
    df = yf.download(ticker, start="1997-01-01", multi_level_index=False)
except TypeError:
    df = yf.download(ticker, start="1997-01-01")

# 2. Extract Close price and resample to Month-End (ME)
# (If your pandas is older than 2.2, change 'ME' to 'M')
monthly_fx = df['Close'].resample('ME').last().dropna()

# 3. Format column names cleanly for SQLite
monthly_df = monthly_fx.to_frame(name="fx_rate")
monthly_df.index = monthly_df.index.strftime('%Y-%m')
monthly_df.index.name = 'year_month'

# 4. Save to CSV in your project folder
output_file = "usd_egp_monthly.csv"
monthly_df.to_csv(output_file)
print(f"Monthly exchange rate CSV saved successfully to {output_file}!")
print(monthly_df.tail())